describe('File Upload Success Checkmark', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display success checkmark when file is fully uploaded', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload/files', {
      statusCode: 200,
      body: {
        fileId: '12345',
        fileName: 'test-file.pdf',
        fileSize: 1024,
        status: 'success'
      }
    }).as('fileUploadSuccess');

    // Select file input and upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf', {
      force: true
    });

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'File uploaded successfully');

    // Verify success checkmark icon is displayed
    cy.get('[data-testid="success-checkmark"]').should('be.visible');
    cy.get('[data-testid="success-checkmark"]').should('contain', '✓');

    // Verify file details are displayed
    cy.get('[data-testid="file-name"]').should('contain', 'test-file.pdf');
    cy.get('[data-testid="file-size"]').should('contain', '1024 bytes');

    // Verify file ID is displayed
    cy.get('[data-testid="file-id"]').should('contain', '12345');

    // Verify upload button is disabled
    cy.get('[data-testid="upload-button"]').should('be.disabled');

    // Verify success API call was made
    cy.wait('@fileUploadSuccess').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
  });

  it('should not display success checkmark when upload fails', () => {
    // Intercept the file upload API call with error response
    cy.intercept('POST', '/api/upload/files', {
      statusCode: 500,
      body: {
        error: 'Internal Server Error',
        fileId: null
      }
    }).as('fileUploadFailure');

    // Select file input and upload a file
    cy.get('[data-testid="file-input"]').selectFile('cypress/fixtures/test-file.pdf', {
      force: true
    });

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Upload failed');

    // Verify success checkmark is not displayed
    cy.get('[data-testid="success-checkmark"]').should('not.exist');

    // Verify upload button is enabled
    cy.get('[data-testid="upload-button"]').should('not.be.disabled');

    // Verify error API call was made
    cy.wait('@fileUploadFailure').then((interception) => {
      expect(interception.response.statusCode).to.equal(500);
    });
  });
});
